public static int calculateTimeNeeded(int N) {
  if (N <= 0) {
    throw new IllegalArgumentException("N must be a positive integer.");
  }

  int timeNeeded = 0;

  for (int i = 0; i < N; i++) {
    int leftPerson = (i - 1 + N) % N; // The person who was originally on their left
    int rightPerson = (i + 1) % N; // The person who was originally on their right

    timeNeeded += Math.min(leftPerson, rightPerson);
  }

  return timeNeeded;
}

public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> permutations = new ArrayList<>();

    permuteHelper(nums, 0, new ArrayList<>(), permutations);

    return permutations;
}

private void permuteHelper(int[] nums, int index, List<Integer> currentPermutation, List<List<Integer>> permutations) {
    if (index == nums.length) {
        permutations.add(new ArrayList<>(currentPermutation));
        return;
    }

    for (int i = 0; i < nums.length; i++) {
        int num = nums[i];

        if (!currentPermutation.contains(num)) {
            currentPermutation.add(num);
            permuteHelper(nums, index + 1, currentPermutation, permutations);
            currentPermutation.remove(currentPermutation.size() - 1);
        }
    }
}

public int findLargestSubstring(List<String> strings) {
    // Initialize the largest substring as an empty string
    String largestSubstring = "";

    // Loop through each string in the input list
    for (String string : strings) {
        // Reverse the current string
        String reversedString = new StringBuffer(string).reverse().toString();

        // Check if the current string or its reverse is a substring of any of the input strings
        if (string.contains(reversedString) || reversedString.contains(string)) {
            // If either the current string or its reverse is a substring of any of the input strings,
            // set the largest substring to the current string
            largestSubstring = string;
            break;
        }
    }

    // Return the length of the largest substring
    return largestSubstring.length();
}

