public static int maxRegions(int N) {
    // Edge case: N is 0 or negative
    if (N <= 0) {
        return 0;
    }

    // Initialize a bit mask with N bits, where each bit represents a region
    int[] regions = new int[N];
    int numRegions = 0;

    // Iterate over all possible combinations of 3 triangles
    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            for (int k = j + 1; k < N; k++) {
                // If the three triangles form a non-overlapping region,
                // increment the number of regions and set the corresponding
                // bits in the region mask to 1
                if (!regions[i] && !regions[j] && !regions[k]) {
                    regions[i] = regions[j] = regions[k] = 1;
                    numRegions++;
                }
            }
        }
    }

    return numRegions;
}

