public int search(int[] nums, int target) {
    // Define the left and right pointers
    int left = 0;
    int right = nums.length - 1;

    // While the left pointer is less than the right pointer
    while (left <= right) {
        // Find the middle index
        int mid = (left + right) / 2;

        // If the target element is in the middle index
        if (nums[mid] == target) {
            return mid;
        }

        // If the array is sorted and the target is not in the middle index
        if (nums[left] <= nums[mid]) {
            // If the target is less than the middle index, search in the left half
            if (target < nums[mid]) {
                right = mid - 1;
            // If the target is greater than the middle index, search in the right half
            } else {
                left = mid + 1;
            }
        // If the array is rotated and the target is not in the middle index
        } else {
            // If the target is less than the middle index, search in the right half
            if (target < nums[mid]) {
                left = mid + 1;
            // If the target is greater than the middle index, search in the left half
            } else {
                right = mid - 1;
            }
        }
    }

    // If the target is not found, return -1
    return -1;
}

