public String sortString(String s) {
    String result = "";

    for (int i = 0; i < s.length(); i++) {
        int minCharIdx = -1;
        int maxCharIdx = -1;

        for (int j = 0; j < s.length(); j++) {
            char currChar = s.charAt(j);

            if (minCharIdx == -1 || currChar < s.charAt(minCharIdx)) {
                minCharIdx = j;
            }

            if (maxCharIdx == -1 || currChar > s.charAt(maxCharIdx)) {
                maxCharIdx = j;
            }
        }

        result += s.charAt(minCharIdx);
        result += s.charAt(maxCharIdx);

        s = s.replace(s.charAt(minCharIdx), ' ').replace(s.charAt(maxCharIdx), ' ');
    }

    return result;
}

public boolean splitArraySameAverage(int[] nums) {
    // Calculate the sum of the array elements
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    // Calculate the average of the array elements
    double average = (double) sum / nums.length;

    // Check if the average is an integer
    if (average % 1 != 0) {
        return false;
    }

    // Calculate the difference between the average and the minimum element
    int min = Integer.MAX_VALUE;
    for (int num : nums) {
        if (num < min) {
            min = num;
        }
    }
    int diff = (int) (average - min);

    // Check if the difference is evenly divisible by 2
    if (diff % 2 != 0) {
        return false;
    }

    // Check if the difference is greater than or equal to the minimum element
    if (diff < min) {
        return false;
    }

    // Split the array into two subarrays
    int[] subarray1 = new int[nums.length / 2];
    int[] subarray2 = new int[nums.length / 2];
    for (int i = 0; i < nums.length; i++) {
        if (i < subarray1.length) {
            subarray1[i] = nums[i];
        } else {
            subarray2[i - subarray1.length] = nums[i];
        }
    }

    // Calculate the average of the two subarrays
    double subarray1Average = getAverage(subarray1);
    double subarray2Average = getAverage(subarray2);

    // Check if the average of the two subarrays is equal
    return subarray1Average == subarray2Average;
}

private double getAverage(int[] subarray) {
    int sum = 0;
    for (int num : subarray) {
        sum += num;
    }
    return (double) sum / subarray.length;
}

