public int uniqueMorseRepresentations(String[] words) {
    // Unique Morse Code Representations
    //
    // Given an array of strings words where each word can be
    // written as a concatenation of the Morse code of each letter,
    // return the number of different transformations among all words.
    //
    // Example 1:
    // Input: words = ["gin", "zen", "gig", "msg"]
    // Output: 2
    // Explanation:
    // The transformation of each word is:
    // - "gin" -> "--..."
    // - "zen" -> "--.."
    // - "gig" -> "--."
    // - "msg" -> "--.."
    // There are 2 different transformations: "--..." and "--..".
    //
    // Example 2:
    // Input: words = ["a"]
    // Output: 1
    // Explanation: We can transform the word "a" into ".-", so the
    // number of unique Morse Code transformations is 1.

    // Map to store Morse code for each letter
    Map<Character, String> morseCode = new HashMap<>();
    morseCode.put('a', ".-");
    morseCode.put('b', "-...");
    morseCode.put('c', "-.-.");
    morseCode.put('d', "-..");
    morseCode.put('e', ".");
    morseCode.put('f', "..-.");
    morseCode.put('g', "--.");
    morseCode.put('h', "....");
    morseCode.put('i', "..");
    morseCode.put('j', ".---");
    morseCode.put('k', "-.-");
    morseCode.put('l', ".-..");
    morseCode.put('m', "--");
    morseCode.put('n', "-.");
    morseCode.put('o', "---");
    morseCode.put('p', ".--.");
    morseCode.put('q', "--.-");
    morseCode.put('r', ".-.");
    morseCode.put('s', "...");
    morseCode.put('t', "-");
    morseCode.put('u', "..-");
    morseCode.put('v', "...-");
    morseCode.put('w', ".--");
    morseCode.put('x', "-..-");
    morseCode.put('y', "-.--");
    morseCode.put('z', "--..");

    // Set to store unique Morse Code transformations
    Set<String> uniqueMorseCodes = new HashSet<>();

    // Loop through each word
    for (String word : words) {
        // Convert word to Morse code
        String morseWord = "";
        for (char ch : word.toCharArray()) {
            morseWord += morseCode.get(ch);
        }

        // Add Morse Code transformation to set
        uniqueMorseCodes.add(morseWord);
    }

    // Return number of unique Morse Code transformations
    return uniqueMorseCodes.size();
}

