public int minInsertions(String s) {
    int balance = 0;
    int minOperations = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            balance--;
            if (balance < 0) {
                balance++;
                minOperations++;
            }
        }
    }

    // Handle any left over braces
    while (balance > 0) {
        balance--;
        minOperations++;
    }

    return minOperations;
}

public int minOperations(int n) {
    if (n == 1) {
        return 0;
    }

    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    int minOperations = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (arr[i] != arr[j]) {
                minOperations++;
                int x = Math.min(i, j);
                int y = Math.max(i, j);
                arr[x]--;
                arr[y]++;
            }
        }
    }

    return minOperations;
}

