public int maxAbsoluteSum(int[] nums) {
    // Initialize variables
    int maxSum = 0;
    int currentSum = 0;

    // Iterate over the array
    for (int i = 0; i < nums.length; i++) {
        // Update the current sum
        currentSum += nums[i];

        // Update the maximum sum
        maxSum = Math.max(maxSum, currentSum);

        // Update the current sum if it is negative
        if (currentSum < 0) {
            currentSum = 0;
        }
    }

    // Return the maximum absolute sum
    return Math.max(maxSum, -currentSum);
}

public int findMinFibonacciNumbers(int k) {
    // Edge case: k = 1
    if (k == 1) {
        return 1;
    }

    // Initialize the Fibonacci sequence to 1, 1
    int f1 = 1, f2 = 1;

    // Loop until the sum of the Fibonacci sequence is equal to k
    while (f1 + f2 < k) {
        // Compute the next term in the Fibonacci sequence
        int f3 = f1 + f2;
        // Replace f1 with f2, f2 with f3, and f1 with f3
        f1 = f2;
        f2 = f3;
    }

    // Return the minimum number of Fibonacci numbers whose sum is equal to k
    return Math.min(f1, f2) + 1;
}

public int kthFactor(int n, int k) {
    if (k <= 0 || n <= 0) {
        return -1;
    }
    int[] factors = new int[n];
    int count = 0;
    for (int i = 1; i <= n; i++) {
        if (n % i == 0) {
            factors[count++] = i;
        }
    }
    if (count < k) {
        return -1;
    }
    return factors[k - 1];
}

