public static double calculateProbability(int n) {
        // We need to calculate n! / (k! (n-k)!) where k = n.
        // For example, in the case where n = 6, we would have n! = 6! = 720 and k! = 6! = 720.
        // Similarly, in the case where n = 12, we would have n! = 12! = 479001600 and k! = 12! = 479001600.
        // We can use the following formula to calculate n! and k!:
        int nFactorial = IntStream.rangeClosed(1, n).reduce((a, b) -> a * b).orElseThrow();
        int kFactorial = IntStream.rangeClosed(1, n).filter(i -> i <= k).reduce((a, b) -> a * b).orElseThrow();

        // Now, we can use the formula for the probability (n! / (k! (n-k)!)) to calculate the result:
        return (double) nFactorial / (kFactorial * (nFactorial - kFactorial));
    }

