        }
    }

    // Find the element that appears once
    for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
        if (entry.getValue() == 1) {
            return entry.getKey();
        }
    }

    // If no element appears once, return -1
    return -1;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> steppingNumbers = new ArrayList<>();
    for (int i = low; i <= high; i++) {
        String numString = Integer.toString(i);
        int length = numString.length();
        for (int j = 0; j < length - 1; j++) {
            int digit = Integer.parseInt(String.valueOf(numString.charAt(j)));
            int nextDigit = Integer.parseInt(String.valueOf(numString.charAt(j + 1)));
            if (digit == nextDigit + 1 || digit == nextDigit - 1) {
                steppingNumbers.add(i);
                break;
            }
        }
    }
    return steppingNumbers;
}

