}

public static int addDigits(int num) {
    // Base case: if num is already a single digit, return it
    if (num < 10) {
        return num;
    }

    // Recursive case: add all digits and repeat the process
    int sum = 0;
    while (num > 0) {
        sum += num % 10;
        num /= 10;
    }
    return addDigits(sum);
}

