        return false;
    }

    // Sort the points in the array by the x values
    Arrays.sort(points, Comparator.comparingInt(point -> point[0]));

    // Check if the first and last points have the same x value
    if (points[0][0] == points[2][0]) {
        return false;
    }

    // Check if the second point is between the first and last points
    // in the sorted array
    int[] secondPoint = points[1];
    if (secondPoint[0] < points[0][0] || secondPoint[0] > points[2][0]) {
        return false;
    }

    // If all checks pass, return true
    return true;
}

