public static int calculateUniqueSum(int[] nums) {
    // Initiate a set to store unique elements
    Set<Integer> uniqueSet = new HashSet<>();

    // Loop through each number in the input array
    for (int num : nums) {
        // If the current number is not in the set, add it to the set
        if (!uniqueSet.contains(num)) {
            uniqueSet.add(num);
        }
    }

    // Initialize the sum to 0
    int sum = 0;

    // Loop through the set of unique elements
    for (Integer num : uniqueSet) {
        // Add the current element to the sum
        sum += num;
    }

    // Return the sum
    return sum;
}

public static int minPerfectSquareSum(int n) {

    // Initialize a hash set to keep track of perfect square numbers
    Set<Integer> perfectSquares = new HashSet<>();

    // Initialize a variable to keep track of the minimum number of perfect square numbers
    int minSquares = n;

    // Iterate from 1 to n
    for (int i = 1; i <= n; i++) {

        // Check if i is a perfect square
        if (Math.sqrt(i) % 1 == 0) {

            // If i is a perfect square, add it to the hash set
            perfectSquares.add(i);

            // Check if the sum of the perfect square numbers in the hash set is less than or equal to n
            if (perfectSquares.stream().mapToInt(Integer::intValue).sum() <= n) {

                // If the sum of the perfect square numbers in the hash set is less than or equal to n, update the minimum number of perfect square numbers
                minSquares = Math.min(minSquares, perfectSquares.size());
            }
        }
    }

    // Return the minimum number of perfect square numbers
    return minSquares;
}

